namespace ghidra.graph.viewer.actions;

using docking;
using ghidra.graph;
using ghidra.graph.viewer;

/**
 * Context for a {@link VisualGraph} when a vertex is selected
 *
 * @param <V> the vertex type
 */
public class VgVertexContext<V> : VgActionContext, VisualGraphVertexActionContext<V> where V : VisualVertex {

	private V v;

	public VgVertexContext(ComponentProvider provider, V v) : base(provider)
    {
		this.v = v;
	}

	/* @Override */
	public V getVertex() {
		return v;
	}

	/* @Override */
	public bool shouldShowSatelliteActions() {
		return false; // not satellite actions when we are over a vertex
	}
}
